static STRUCT_Balloon: StructMeta = StructMeta {
    name: "balloon",
    doc: "Request the balloon driver to change its balloon size.\n\nErrors:\n    - If the balloon driver is enabled but not functional because\n      the KVM kernel module cannot support it, KVMMissingCap\n    - If no balloon device is present, DeviceNotActive\n\n.. note:: This command just issues a request to the guest.  When it\n   returns, the balloon size may not have changed.  A guest can\n   change the balloon size independent of this command.\n\n\n.. qmp-example::\n   :annotated:\n\n   ::\n\n     -> { \"execute\": \"balloon\", \"arguments\": { \"value\": 536870912 } }\n     <- { \"return\": {} }\n\n   With a 2.5GiB guest this command inflated the ballon to 3GiB.",
    fields: &FIELDS_Balloon,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (1u32, 1u32, 0u32),
    until: None,
};
