static VARIANTS_BiosAtaTranslation: &[EnumVariantMeta] = &[
    EnumVariantMeta { name: "Auto", wire_name: "auto", payload_struct: None, payload_type: None, since: (2u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "If cylinder/heads/sizes are passed, choose between none and\nLBA depending on the size of the disk.  If they are not passed,\nchoose none if QEMU can guess that the disk had 16 or fewer\nheads, large if QEMU can guess that the disk had 131072 or fewer\ntracks across all heads (i.e. cylinders*heads<131072), otherwise\nLBA." },
    EnumVariantMeta { name: "None", wire_name: "none", payload_struct: None, payload_type: None, since: (2u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "The physical disk geometry is equal to the logical geometry." },
    EnumVariantMeta { name: "Lba", wire_name: "lba", payload_struct: None, payload_type: None, since: (2u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Assume 63 sectors per track and one of 16, 32, 64, 128 or 255\nheads (if fewer than 255 are enough to cover the whole disk with\n1024 cylinders/head).  The number of cylinders/head is then\ncomputed based on the number of sectors and heads." },
    EnumVariantMeta { name: "Large", wire_name: "large", payload_struct: None, payload_type: None, since: (2u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "The number of cylinders per head is scaled down to 1024 by\ncorrespondingly scaling up the number of heads." },
    EnumVariantMeta { name: "Rechs", wire_name: "rechs", payload_struct: None, payload_type: None, since: (2u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Same as @large, but first convert a 16-head geometry to\n15-head, by proportionally scaling up the number of\ncylinders/head." },
];
