static STRUCT_BlockdevBackup: StructMeta = StructMeta {
    name: "blockdev-backup",
    doc: "Start a point-in-time copy of a block device to a new destination.\nThe status of ongoing `blockdev-backup` operations can be checked\nwith `query-block-jobs` where the `BlockJobInfo`.type field has the\nvalue 'backup'.  The operation can be stopped before it has\ncompleted using the `job-cancel` or `block-job-cancel` command.\n\nErrors:\n    - If @device is not a valid block device, DeviceNotFound\n\n\n.. qmp-example::\n\n    -> { \"execute\": \"blockdev-backup\",\n         \"arguments\": { \"device\": \"src-id\",\n                        \"sync\": \"full\",\n                        \"target\": \"tgt-id\" } }\n    <- { \"return\": {} }",
    fields: &FIELDS_BlockdevBackup,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (2u32, 3u32, 0u32),
    until: None,
};
