static STRUCT_BlockdevChangeMedium: StructMeta = StructMeta {
    name: "blockdev-change-medium",
    doc: "Changes the medium inserted into a block device by ejecting the\ncurrent medium and loading a new image file which is inserted as the\nnew medium (this command combines `blockdev-open-tray`,\n`blockdev-remove-medium`, `blockdev-insert-medium` and\n`blockdev-close-tray`).\n\nFeatures:\n\n@deprecated: Member @device is deprecated.  Use @id instead.\n\n\n.. qmp-example::\n   :title: Change a removable medium\n\n    -> { \"execute\": \"blockdev-change-medium\",\n         \"arguments\": { \"id\": \"ide0-1-0\",\n                        \"filename\": \"/srv/images/Fedora-12-x86_64-DVD.iso\",\n                        \"format\": \"raw\" } }\n    <- { \"return\": {} }\n\n.. qmp-example::\n   :title: Load a read-only medium into a writable drive\n\n    -> { \"execute\": \"blockdev-change-medium\",\n         \"arguments\": { \"id\": \"floppyA\",\n                        \"filename\": \"/srv/images/ro.img\",\n                        \"format\": \"raw\",\n                        \"read-only-mode\": \"retain\" } }\n\n    <- { \"error\":\n         { \"class\": \"GenericError\",\n           \"desc\": \"Could not open '/srv/images/ro.img': Permission denied\" } }\n\n    -> { \"execute\": \"blockdev-change-medium\",\n         \"arguments\": { \"id\": \"floppyA\",\n                        \"filename\": \"/srv/images/ro.img\",\n                        \"format\": \"raw\",\n                        \"read-only-mode\": \"read-only\" } }\n\n    <- { \"return\": {} }",
    fields: &FIELDS_BlockdevChangeMedium,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (2u32, 5u32, 0u32),
    until: None,
};
