static VARIANTS_BlockdevOnError: &[EnumVariantMeta] = &[
    EnumVariantMeta { name: "Report", wire_name: "report", payload_struct: None, payload_type: None, since: (1u32, 3u32, 0u32), until: None, deprecated: false, unstable: false, doc: "for guest operations, report the error to the guest; for\njobs, cancel the job" },
    EnumVariantMeta { name: "Ignore", wire_name: "ignore", payload_struct: None, payload_type: None, since: (1u32, 3u32, 0u32), until: None, deprecated: false, unstable: false, doc: "ignore the error, only report a QMP event (`BLOCK_IO_ERROR`\nor `BLOCK_JOB_ERROR`).  The backup, mirror and commit block jobs\nretry the failing request later and may still complete\nsuccessfully.  The stream block job continues to stream and will\ncomplete with an error." },
    EnumVariantMeta { name: "Enospc", wire_name: "enospc", payload_struct: None, payload_type: None, since: (1u32, 3u32, 0u32), until: None, deprecated: false, unstable: false, doc: "same as @stop on ENOSPC, same as @report otherwise." },
    EnumVariantMeta { name: "Stop", wire_name: "stop", payload_struct: None, payload_type: None, since: (1u32, 3u32, 0u32), until: None, deprecated: false, unstable: false, doc: "for guest operations, stop the virtual machine; for jobs,\npause the job" },
    EnumVariantMeta { name: "Auto", wire_name: "auto", payload_struct: None, payload_type: None, since: (2u32, 7u32, 0u32), until: None, deprecated: false, unstable: false, doc: "inherit the error handling policy of the backend (since: 2.7)" },
];
