static STRUCT_BlockdevRemoveMedium: StructMeta = StructMeta {
    name: "blockdev-remove-medium",
    doc: "Removes a medium (a block driver state tree) from a block device.\nThat block device's tray must currently be open (unless there is no\nattached guest device).\n\nIf the tray is open and there is no medium inserted, this will be a\nno-op.\n\n\n.. qmp-example::\n\n    -> { \"execute\": \"blockdev-remove-medium\",\n         \"arguments\": { \"id\": \"ide0-1-0\" } }\n\n    <- { \"error\": { \"class\": \"GenericError\",\n                    \"desc\": \"Tray of device 'ide0-1-0' is not open\" } }\n\n    -> { \"execute\": \"blockdev-open-tray\",\n         \"arguments\": { \"id\": \"ide0-1-0\" } }\n\n    <- { \"timestamp\": { \"seconds\": 1418751627,\n                        \"microseconds\": 549958 },\n         \"event\": \"DEVICE_TRAY_MOVED\",\n         \"data\": { \"device\": \"ide1-cd0\",\n                   \"id\": \"ide0-1-0\",\n                   \"tray-open\": true } }\n\n    <- { \"return\": {} }\n\n    -> { \"execute\": \"blockdev-remove-medium\",\n         \"arguments\": { \"id\": \"ide0-1-0\" } }\n\n    <- { \"return\": {} }",
    fields: &FIELDS_BlockdevRemoveMedium,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (2u32, 12u32, 0u32),
    until: None,
};
