static STRUCT_BlockdevSnapshotDeleteInternalSync: StructMeta = StructMeta {
    name: "blockdev-snapshot-delete-internal-sync",
    doc: "Synchronously delete an internal snapshot of a block device, when\nthe format of the image used support it.  The snapshot is identified\nby name or id or both.  One of the name or id is required.  Return\n`SnapshotInfo` for the successfully deleted snapshot.\n\nErrors:\n    - If @device is not a valid block device, GenericError\n    - If snapshot not found, GenericError\n    - If the format of the image used does not support it,\n      GenericError\n    - If @id and @name are both not specified, GenericError\n\n\n.. qmp-example::\n\n    -> { \"execute\": \"blockdev-snapshot-delete-internal-sync\",\n         \"arguments\": { \"device\": \"ide-hd0\",\n                        \"name\": \"snapshot0\" }\n       }\n    <- { \"return\": {\n                       \"id\": \"1\",\n                       \"name\": \"snapshot0\",\n                       \"vm-state-size\": 0,\n                       \"date-sec\": 1000012,\n                       \"date-nsec\": 10,\n                       \"vm-clock-sec\": 100,\n                       \"vm-clock-nsec\": 20,\n                       \"icount\": 220414\n         }\n       }",
    fields: &FIELDS_BlockdevSnapshotDeleteInternalSync,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (1u32, 7u32, 0u32),
    until: None,
};
