static VARIANTS_BlockPermission: &[EnumVariantMeta] = &[
    EnumVariantMeta { name: "ConsistentRead", wire_name: "consistent-read", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "A user that has the \"permission\" of consistent\nreads is guaranteed that their view of the contents of the block\ndevice is complete and self-consistent, representing the\ncontents of a disk at a specific point.  For most block devices\n(including their backing files) this is true, but the property\ncannot be maintained in a few situations like for intermediate\nnodes of a commit block job." },
    EnumVariantMeta { name: "Write", wire_name: "write", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "This permission is required to change the visible disk\ncontents." },
    EnumVariantMeta { name: "WriteUnchanged", wire_name: "write-unchanged", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "This permission (which is weaker than\nBLK_PERM_WRITE) is both enough and required for writes to the\nblock node when the caller promises that the visible disk\ncontent doesn't change.  As the BLK_PERM_WRITE permission is\nstrictly stronger, either is sufficient to perform an unchanging\nwrite." },
    EnumVariantMeta { name: "Resize", wire_name: "resize", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "This permission is required to change the size of a block\nnode." },
    EnumVariantMeta { name: "GraphMod", wire_name: "graph-mod", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: Some((7u32, 0u32, 0u32)), deprecated: false, unstable: false, doc: "This permission is required to change the node that this\nBdrvChild points to." },
];
