static STRUCT_BlockSetWriteThreshold: StructMeta = StructMeta {
    name: "block-set-write-threshold",
    doc: "Change the write threshold for a block drive.  An event will be\ndelivered if a write to this block drive crosses the configured\nthreshold.  The threshold is an offset, thus must be non-negative.\nDefault is no write threshold.  Setting the threshold to zero\ndisables it.\n\nThis is useful to transparently resize thin-provisioned drives\nwithout the guest OS noticing.\n\n\n.. qmp-example::\n\n    -> { \"execute\": \"block-set-write-threshold\",\n         \"arguments\": { \"node-name\": \"mydev\",\n                        \"write-threshold\": 17179869184 } }\n    <- { \"return\": {} }",
    fields: &FIELDS_BlockSetWriteThreshold,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (2u32, 3u32, 0u32),
    until: None,
};
