static VARIANTS_CpuModelExpansionType: &[EnumVariantMeta] = &[
    EnumVariantMeta { name: "Static", wire_name: "static", payload_struct: None, payload_type: None, since: (2u32, 8u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Expand to a static CPU model, a combination of a static\nbase model name and property delta changes.  As the static base\nmodel will never change, the expanded CPU model will be the\nsame, independent of QEMU version, machine type, machine\noptions, and accelerator options.  Therefore, the resulting\nmodel can be used by tooling without having to specify a\ncompatibility machine - e.g. when displaying the \"host\" model.\nThe @static CPU models are migration-safe." },
    EnumVariantMeta { name: "Full", wire_name: "full", payload_struct: None, payload_type: None, since: (2u32, 8u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Expand all properties.  The produced model is not guaranteed\nto be migration-safe, but allows tooling to get an insight and\nwork with model details." },
];
static ENUM_CpuModelExpansionType: EnumMeta = EnumMeta {
    name: "CpuModelExpansionType",
    wire_name: "CpuModelExpansionType",
    doc: "An enumeration of CPU model expansion types.\n\n.. note:: When a non-migration-safe CPU model is expanded in static\n   mode, some features enabled by the CPU model may be omitted,\n   because they can't be implemented by a static CPU model\n   definition (e.g. cache info passthrough and PMU passthrough in\n   x86).  If you need an accurate representation of the features\n   enabled by a non-migration-safe CPU model, use @full.  If you\n   need a static representation that will keep ABI compatibility\n   even when changing QEMU version or machine-type, use @static (but\n   keep in mind that some features may be omitted).",
    variants: &VARIANTS_CpuModelExpansionType,
    kind: EnumKind::Unit,
    since: (2u32, 8u32, 0u32),
    until: None,
};
