static VARIANTS_DirtyBitmapStatus: &[EnumVariantMeta] = &[
    EnumVariantMeta { name: "Active", wire_name: "active", payload_struct: None, payload_type: None, since: (2u32, 4u32, 0u32), until: None, deprecated: false, unstable: false, doc: "The bitmap is actively monitoring for new writes, and can be cleared,\ndeleted, or used for backup operations." },
    EnumVariantMeta { name: "Disabled", wire_name: "disabled", payload_struct: None, payload_type: None, since: (2u32, 4u32, 0u32), until: None, deprecated: false, unstable: false, doc: "The bitmap is not currently recording new writes by the guest.\nThis is requested explicitly via @block-dirty-bitmap-disable.\nIt can still be cleared, deleted, or used for backup operations." },
    EnumVariantMeta { name: "Frozen", wire_name: "frozen", payload_struct: None, payload_type: None, since: (2u32, 4u32, 0u32), until: None, deprecated: false, unstable: false, doc: "The bitmap is currently in-use by some operation and is immutable.\nIf the bitmap was @active prior to the operation, new writes by the\nguest are being recorded in a temporary buffer, and will not be lost.\nGenerally, bitmaps are cleared on successful use in an operation and\nthe temporary buffer is committed into the bitmap. On failure, the\ntemporary buffer is merged back into the bitmap without first\nclearing it.\nPlease refer to the documentation for each bitmap-using operation,\nSee also @blockdev-backup, @drive-backup." },
    EnumVariantMeta { name: "Locked", wire_name: "locked", payload_struct: None, payload_type: None, since: (2u32, 12u32, 0u32), until: None, deprecated: false, unstable: false, doc: "The bitmap is currently in-use by some operation and is immutable.\nIf the bitmap was @active prior to the operation, it is still\nrecording new writes. If the bitmap was @disabled, it is not\nrecording new writes. (Since 2.12)" },
    EnumVariantMeta { name: "Inconsistent", wire_name: "inconsistent", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "This is a persistent dirty bitmap that was marked in-use on\ndisk, and is unusable by QEMU. It can only be deleted.\nPlease rely on the inconsistent field in @BlockDirtyInfo\ninstead, as the status field is deprecated. (Since 4.0)" },
];
