static FIELDS_DumpGuestMemory: &[FieldMeta] = &[
    FieldMeta { name: "paging", wire_name: "paging", ty: 9, optional: false, is_discriminator: false, recursive: false, since: (1u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "if true, do paging to get guest's memory mapping.  This\nallows using gdb to process the core file.\n\n**Important**: this option can make QEMU allocate several\ngigabytes of RAM.  This can happen for a large guest, or a\nmalicious guest pretending to be large.\n\nAlso, paging=true has the following limitations:\n\n1. The guest may be in a catastrophic state or can have\n   corrupted memory, which cannot be trusted\n2. The guest can be in real-mode even if paging is enabled.  For\n   example, the guest uses ACPI to sleep, and ACPI sleep state\n   goes in real-mode\n3. Currently only supported on i386 and x86_64." },
    FieldMeta { name: "protocol", wire_name: "protocol", ty: 4, optional: false, is_discriminator: false, recursive: false, since: (1u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "the filename or file descriptor of the vmcore.  The\nsupported protocols are:\n\n1. file: the protocol starts with \"file:\", and the following\n   string is the file's path.\n2. fd: the protocol starts with \"fd:\", and the following string\n   is the fd's name." },
    FieldMeta { name: "begin", wire_name: "begin", ty: 7, optional: true, is_discriminator: false, recursive: false, since: (1u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "if specified, the starting physical address." },
    FieldMeta { name: "length", wire_name: "length", ty: 7, optional: true, is_discriminator: false, recursive: false, since: (1u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "if specified, the memory size, in bytes.  If you don't want\nto dump all guest's memory, please specify the start @begin and\n@length" },
    FieldMeta { name: "format", wire_name: "format", ty: 339, optional: true, is_discriminator: false, recursive: false, since: (2u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "if specified, the format of guest memory dump.  But non-elf\nformat is conflict with paging and filter, ie.  @paging, @begin\nand @length is not allowed to be specified with non-elf @format\nat the same time (since 2.0)" },
    FieldMeta { name: "detach", wire_name: "detach", ty: 9, optional: true, is_discriminator: false, recursive: false, since: (2u32, 6u32, 0u32), until: None, deprecated: false, unstable: false, doc: "if true, QMP will return immediately rather than waiting\nfor the dump to finish.  The user can track progress using\n`query-dump`.  (since 2.6)." },
];
