static STRUCT_JobCancel: StructMeta = StructMeta {
    name: "job-cancel",
    doc: "Instruct an active background job to cancel at the next opportunity.\nThis command returns immediately after marking the active job for\ncancellation.\n\nThe job will cancel as soon as possible and then emit a\n`JOB_STATUS_CHANGE` event.  Usually, the status will change to\nABORTING, but it is possible that a job successfully completes (e.g.\nbecause it was almost done and there was no opportunity to cancel\nearlier than completing the job) and transitions to PENDING instead.",
    fields: &FIELDS_JobCancel,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (3u32, 0u32, 0u32),
    until: None,
};
