static VARIANTS_LostTickPolicy: &[EnumVariantMeta] = &[
    EnumVariantMeta { name: "Discard", wire_name: "discard", payload_struct: None, payload_type: None, since: (2u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "throw away the missed ticks and continue with future\ninjection normally.  The guest OS will see the timer jump ahead\nby a potentially quite significant amount all at once, as if the\nintervening chunk of time had simply not existed; needless to\nsay, such a sudden jump can easily confuse a guest OS which is\nnot specifically prepared to deal with it.  Assuming the guest\nOS can deal correctly with the time jump, the time in the guest\nand in the host should now match." },
    EnumVariantMeta { name: "Delay", wire_name: "delay", payload_struct: None, payload_type: None, since: (2u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "continue to deliver ticks at the normal rate.  The guest OS\nwill not notice anything is amiss, as from its point of view\ntime will have continued to flow normally.  The time in the\nguest should now be behind the time in the host by exactly the\namount of time during which ticks have been missed." },
    EnumVariantMeta { name: "Merge", wire_name: "merge", payload_struct: None, payload_type: None, since: (2u32, 0u32, 0u32), until: Some((4u32, 1u32, 0u32)), deprecated: false, unstable: false, doc: "merge the missed tick(s) into one tick and inject.  Guest time\nmay be delayed, depending on how the OS reacts to the merging\nof ticks" },
    EnumVariantMeta { name: "Slew", wire_name: "slew", payload_struct: None, payload_type: None, since: (2u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "deliver ticks at a higher rate to catch up with the missed\nticks.  The guest OS will not notice anything is amiss, as from\nits point of view time will have continued to flow normally.\nOnce the timer has managed to catch up with all the missing\nticks, the time in the guest and in the host should match." },
];
