static STRUCT_Migrate: StructMeta = StructMeta {
    name: "migrate",
    doc: "Migrates the current running guest to another Virtual Machine.\n\n\n.. admonition:: Notes\n\n    1. The `query-migrate` command should be used to check\n       migration's progress and final result (this information is\n       provided by the 'status' member).\n\n    2. The uri argument should have the Uniform Resource Identifier\n       of default destination VM.  This connection will be bound to\n       default network.\n\n    3. For now, number of migration streams is restricted to one,\n       i.e. number of items in 'channels' list is just 1.\n\n    4. The 'uri' and 'channels' arguments are mutually exclusive;\n       exactly one of the two should be present.\n\n.. qmp-example::\n\n    -> { \"execute\": \"migrate\", \"arguments\": { \"uri\": \"tcp:0:4446\" } }\n    <- { \"return\": {} }\n\n    -> { \"execute\": \"migrate\",\n         \"arguments\": {\n             \"channels\": [ { \"channel-type\": \"main\",\n                             \"addr\": { \"transport\": \"socket\",\n                                       \"type\": \"inet\",\n                                       \"host\": \"10.12.34.9\",\n                                       \"port\": \"1050\" } } ] } }\n    <- { \"return\": {} }\n\n    -> { \"execute\": \"migrate\",\n         \"arguments\": {\n             \"channels\": [ { \"channel-type\": \"main\",\n                             \"addr\": { \"transport\": \"exec\",\n                                       \"args\": [ \"/bin/nc\", \"-p\", \"6000\",\n                                                 \"/some/sock\" ] } } ] } }\n    <- { \"return\": {} }\n\n    -> { \"execute\": \"migrate\",\n         \"arguments\": {\n             \"channels\": [ { \"channel-type\": \"main\",\n                             \"addr\": { \"transport\": \"rdma\",\n                                       \"host\": \"10.12.34.9\",\n                                       \"port\": \"1050\" } } ] } }\n    <- { \"return\": {} }\n\n    -> { \"execute\": \"migrate\",\n         \"arguments\": {\n             \"channels\": [ { \"channel-type\": \"main\",\n                             \"addr\": { \"transport\": \"file\",\n                                       \"filename\": \"/tmp/migfile\",\n                                       \"offset\": \"0x1000\" } } ] } }\n    <- { \"return\": {} }",
    fields: &FIELDS_Migrate,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (1u32, 1u32, 0u32),
    until: None,
};
