static VARIANTS_MigrationCapability: &[EnumVariantMeta] = &[
    EnumVariantMeta { name: "Xbzrle", wire_name: "xbzrle", payload_struct: None, payload_type: None, since: (1u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Migration supports xbzrle (Xor Based Zero Run Length\nEncoding).  This feature allows us to minimize migration traffic\nfor certain work loads, by sending compressed difference of the\npages" },
    EnumVariantMeta { name: "XRdmaPinAll", wire_name: "x-rdma-pin-all", payload_struct: None, payload_type: None, since: (1u32, 6u32, 0u32), until: Some((2u32, 0u32, 0u32)), deprecated: false, unstable: false, doc: "Controls whether or not the entire VM memory footprint is\nmlock()'d on demand or all at once. Refer to docs/rdma.txt for usage.\nDisabled by default. Experimental: may (or may not) be renamed after\nfurther testing is complete. (since 1.6)" },
    EnumVariantMeta { name: "AutoConverge", wire_name: "auto-converge", payload_struct: None, payload_type: None, since: (1u32, 6u32, 0u32), until: None, deprecated: false, unstable: false, doc: "If enabled, QEMU will automatically throttle down\nthe guest to speed up convergence of RAM migration.  (since 1.6)" },
    EnumVariantMeta { name: "ZeroBlocks", wire_name: "zero-blocks", payload_struct: None, payload_type: None, since: (1u32, 6u32, 0u32), until: Some((11u32, 0u32, 0u32)), deprecated: true, unstable: false, doc: "During storage migration encode blocks of zeroes\nefficiently.  This essentially saves 1MB of zeroes per block on\nthe wire.  Enabling requires source and target VM to support\nthis feature.  To enable it is sufficient to enable the\ncapability on the source VM.  The feature is disabled by\ndefault.  (since 1.6)" },
    EnumVariantMeta { name: "RdmaPinAll", wire_name: "rdma-pin-all", payload_struct: None, payload_type: None, since: (2u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Controls whether or not the entire VM memory\nfootprint is mlock()'d on demand or all at once.  Refer to\ndocs/rdma.txt for usage.  Disabled by default.  (since 2.0)" },
    EnumVariantMeta { name: "Compress", wire_name: "compress", payload_struct: None, payload_type: None, since: (2u32, 4u32, 0u32), until: Some((9u32, 1u32, 0u32)), deprecated: true, unstable: false, doc: "Use multiple compression threads to accelerate live\nmigration.  This feature can help to reduce the migration\ntraffic, by sending compressed pages.  Please note that if\ncompress and xbzrle are both on, compress only takes effect in\nthe ram bulk stage, after that, it will be disabled and only\nxbzrle takes effect, this can help to minimize migration\ntraffic.  The feature is disabled by default.  (since 2.4)" },
    EnumVariantMeta { name: "Events", wire_name: "events", payload_struct: None, payload_type: None, since: (2u32, 4u32, 0u32), until: None, deprecated: false, unstable: false, doc: "generate events for each migration state change (since 2.4)" },
    EnumVariantMeta { name: "XPostcopyRam", wire_name: "x-postcopy-ram", payload_struct: None, payload_type: None, since: (2u32, 5u32, 0u32), until: Some((2u32, 6u32, 0u32)), deprecated: false, unstable: false, doc: "Start executing on the migration target before all of RAM has\nbeen migrated, pulling the remaining pages along as needed. NOTE: If\nthe migration fails during postcopy the VM will fail.  (since 2.5)" },
    EnumVariantMeta { name: "PostcopyRam", wire_name: "postcopy-ram", payload_struct: None, payload_type: None, since: (2u32, 6u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Start executing on the migration target before all of\nRAM has been migrated, pulling the remaining pages along as\nneeded.  The capacity must have the same setting on both source\nand target or migration will not even start.  **Note:** if the\nmigration fails during postcopy the VM will fail.  (since 2.6)" },
    EnumVariantMeta { name: "XColo", wire_name: "x-colo", payload_struct: None, payload_type: None, since: (2u32, 8u32, 0u32), until: None, deprecated: false, unstable: true, doc: "If enabled, migration will never end, and the state of the\nVM on the primary side will be migrated continuously to the VM\non secondary side, this process is called COarse-Grain LOck\nStepping (COLO) for Non-stop Service.  (since 2.8)" },
    EnumVariantMeta { name: "ReleaseRam", wire_name: "release-ram", payload_struct: None, payload_type: None, since: (2u32, 9u32, 0u32), until: None, deprecated: false, unstable: false, doc: "if enabled, QEMU will free the migrated ram pages on\nthe source during postcopy-ram migration.  (since 2.9)" },
    EnumVariantMeta { name: "Block", wire_name: "block", payload_struct: None, payload_type: None, since: (2u32, 10u32, 0u32), until: Some((9u32, 1u32, 0u32)), deprecated: true, unstable: false, doc: "If enabled, QEMU will also migrate the contents of all block\ndevices.  Default is disabled.  A possible alternative uses\nmirror jobs to a builtin NBD server on the destination, which\noffers more flexibility.  (Since 2.10)" },
    EnumVariantMeta { name: "ReturnPath", wire_name: "return-path", payload_struct: None, payload_type: None, since: (2u32, 10u32, 0u32), until: None, deprecated: false, unstable: false, doc: "If enabled, migration will use the return path even\nfor precopy.  (since 2.10)" },
    EnumVariantMeta { name: "PauseBeforeSwitchover", wire_name: "pause-before-switchover", payload_struct: None, payload_type: None, since: (2u32, 11u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Pause outgoing migration before\nserialising device state and before disabling block IO\n(since 2.11)" },
    EnumVariantMeta { name: "XMultifd", wire_name: "x-multifd", payload_struct: None, payload_type: None, since: (2u32, 11u32, 0u32), until: Some((4u32, 0u32, 0u32)), deprecated: false, unstable: false, doc: "Use more than one fd for migration (since 2.11)" },
    EnumVariantMeta { name: "DirtyBitmaps", wire_name: "dirty-bitmaps", payload_struct: None, payload_type: None, since: (2u32, 12u32, 0u32), until: None, deprecated: false, unstable: false, doc: "If enabled, QEMU will migrate named dirty bitmaps.\n(since 2.12)" },
    EnumVariantMeta { name: "PostcopyBlocktime", wire_name: "postcopy-blocktime", payload_struct: None, payload_type: None, since: (3u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Calculate downtime for postcopy live migration\n(since 3.0)" },
    EnumVariantMeta { name: "LateBlockActivate", wire_name: "late-block-activate", payload_struct: None, payload_type: None, since: (3u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "If enabled, the destination will not activate\nblock devices (and thus take locks) immediately at the end of\nmigration.  (since 3.0)" },
    EnumVariantMeta { name: "Multifd", wire_name: "multifd", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Use more than one fd for migration (since 4.0)" },
    EnumVariantMeta { name: "XIgnoreShared", wire_name: "x-ignore-shared", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: true, doc: "If enabled, QEMU will not migrate shared memory\nthat is accessible on the destination machine.  (since 4.0)" },
    EnumVariantMeta { name: "ValidateUuid", wire_name: "validate-uuid", payload_struct: None, payload_type: None, since: (4u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Send the UUID of the source to allow the destination\nto ensure it is the same.  (since 4.2)" },
    EnumVariantMeta { name: "BackgroundSnapshot", wire_name: "background-snapshot", payload_struct: None, payload_type: None, since: (6u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "If enabled, the migration stream will be a\nsnapshot of the VM exactly at the point when the migration\nprocedure starts.  The VM RAM is saved with running VM.\n(since 6.0)" },
    EnumVariantMeta { name: "ZeroCopySend", wire_name: "zero-copy-send", payload_struct: None, payload_type: None, since: (7u32, 1u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Controls behavior on sending memory pages on\nmigration.  When true, enables a zero-copy mechanism for sending\nmemory pages, if host supports it.  Requires that QEMU be\npermitted to use locked memory for guest RAM pages.  (since 7.1)" },
    EnumVariantMeta { name: "PostcopyPreempt", wire_name: "postcopy-preempt", payload_struct: None, payload_type: None, since: (7u32, 1u32, 0u32), until: None, deprecated: false, unstable: false, doc: "If enabled, the migration process will allow\npostcopy requests to preempt precopy stream, so postcopy\nrequests will be handled faster.  This is a performance feature\nand should not affect the correctness of postcopy migration.\n(since 7.1)" },
    EnumVariantMeta { name: "SwitchoverAck", wire_name: "switchover-ack", payload_struct: None, payload_type: None, since: (8u32, 1u32, 0u32), until: None, deprecated: false, unstable: false, doc: "If enabled, migration will not stop the source VM\nand complete the migration until the destination has\nacknowledged that it is OK to switch over.  The acknowledgement\nmay depend, for example, on some device's data being loaded in\nthe destination before doing switchover.  This can reduce\ndowntime if devices that support this capability are present.\nCapability @return-path must be enabled to use it.  (since 8.1)" },
    EnumVariantMeta { name: "DirtyLimit", wire_name: "dirty-limit", payload_struct: None, payload_type: None, since: (8u32, 1u32, 0u32), until: None, deprecated: false, unstable: false, doc: "If enabled, migration will throttle vCPUs as needed to\nkeep their dirty page rate within @vcpu-dirty-limit.  This can\nimprove responsiveness of large guests during live migration,\nand can result in more stable read performance.  Requires KVM\nwith accelerator property \"dirty-ring-size\" set.  (Since 8.1)" },
    EnumVariantMeta { name: "MappedRam", wire_name: "mapped-ram", payload_struct: None, payload_type: None, since: (9u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Migrate using fixed offsets in the migration file for\neach RAM page.  Requires a migration URI that supports seeking,\nsuch as a file.  (since 9.0)" },
];
