static VARIANTS_MigrationParameter: &[EnumVariantMeta] = &[
    EnumVariantMeta { name: "CompressLevel", wire_name: "compress-level", payload_struct: None, payload_type: None, since: (2u32, 4u32, 0u32), until: Some((9u32, 1u32, 0u32)), deprecated: true, unstable: false, doc: "Set the compression level to be used in live\nmigration, the compression level is an integer between 0 and 9,\nwhere 0 means no compression, 1 means the best compression\nspeed, and 9 means best compression ratio which will consume\nmore CPU." },
    EnumVariantMeta { name: "CompressThreads", wire_name: "compress-threads", payload_struct: None, payload_type: None, since: (2u32, 4u32, 0u32), until: Some((9u32, 1u32, 0u32)), deprecated: true, unstable: false, doc: "Set compression thread count to be used in live\nmigration, the compression thread count is an integer between 1\nand 255." },
    EnumVariantMeta { name: "DecompressThreads", wire_name: "decompress-threads", payload_struct: None, payload_type: None, since: (2u32, 4u32, 0u32), until: Some((9u32, 1u32, 0u32)), deprecated: true, unstable: false, doc: "Set decompression thread count to be used in\nlive migration, the decompression thread count is an integer\nbetween 1 and 255. Usually, decompression is at least 4 times as\nfast as compression, so set the decompress-threads to the number\nabout 1/4 of compress-threads is adequate." },
    EnumVariantMeta { name: "XCpuThrottleInitial", wire_name: "x-cpu-throttle-initial", payload_struct: None, payload_type: None, since: (2u32, 5u32, 0u32), until: Some((2u32, 7u32, 0u32)), deprecated: false, unstable: false, doc: "" },
    EnumVariantMeta { name: "XCpuThrottleIncrement", wire_name: "x-cpu-throttle-increment", payload_struct: None, payload_type: None, since: (2u32, 5u32, 0u32), until: Some((2u32, 7u32, 0u32)), deprecated: false, unstable: false, doc: "" },
    EnumVariantMeta { name: "CpuThrottleInitial", wire_name: "cpu-throttle-initial", payload_struct: None, payload_type: None, since: (2u32, 7u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Initial percentage of time guest cpus are\nthrottled when migration auto-converge is activated.  The\ndefault value is 20.  (Since 2.7)" },
    EnumVariantMeta { name: "CpuThrottleIncrement", wire_name: "cpu-throttle-increment", payload_struct: None, payload_type: None, since: (2u32, 7u32, 0u32), until: None, deprecated: false, unstable: false, doc: "throttle percentage increase each time\nauto-converge detects that migration is not making progress.\nThe default value is 10.  (Since 2.7)" },
    EnumVariantMeta { name: "TlsCreds", wire_name: "tls-creds", payload_struct: None, payload_type: None, since: (2u32, 7u32, 0u32), until: None, deprecated: false, unstable: false, doc: "ID of the 'tls-creds' object that provides credentials\nfor establishing a TLS connection over the migration data\nchannel.  On the outgoing side of the migration, the credentials\nmust be for a 'client' endpoint, while for the incoming side the\ncredentials must be for a 'server' endpoint.  Setting this to a\nnon-empty string enables TLS for all migrations.  An empty\nstring means that QEMU will use plain text mode for migration,\nrather than TLS.  (Since 2.7)" },
    EnumVariantMeta { name: "TlsHostname", wire_name: "tls-hostname", payload_struct: None, payload_type: None, since: (2u32, 7u32, 0u32), until: None, deprecated: false, unstable: false, doc: "migration target's hostname for validating the\nserver's x509 certificate identity.  If empty, QEMU will use the\nhostname from the migration URI, if any.  A non-empty value is\nrequired when using x509 based TLS credentials and the migration\nURI does not include a hostname, such as fd: or exec: based\nmigration.  (Since 2.7)\n\nNote: empty value works only since 2.9." },
    EnumVariantMeta { name: "MaxBandwidth", wire_name: "max-bandwidth", payload_struct: None, payload_type: None, since: (2u32, 8u32, 0u32), until: None, deprecated: false, unstable: false, doc: "maximum speed for migration, in bytes per second.\n(Since 2.8)" },
    EnumVariantMeta { name: "DowntimeLimit", wire_name: "downtime-limit", payload_struct: None, payload_type: None, since: (2u32, 8u32, 0u32), until: None, deprecated: false, unstable: false, doc: "set maximum tolerated downtime for migration.\nmaximum downtime in milliseconds (Since 2.8)" },
    EnumVariantMeta { name: "XCheckpointDelay", wire_name: "x-checkpoint-delay", payload_struct: None, payload_type: None, since: (2u32, 8u32, 0u32), until: None, deprecated: false, unstable: true, doc: "The delay time (in ms) between two COLO\ncheckpoints in periodic mode.  (Since 2.8)" },
    EnumVariantMeta { name: "BlockIncremental", wire_name: "block-incremental", payload_struct: None, payload_type: None, since: (2u32, 10u32, 0u32), until: Some((9u32, 1u32, 0u32)), deprecated: true, unstable: false, doc: "Affects how much storage is migrated when the\nblock migration capability is enabled.  When false, the entire\nstorage backing chain is migrated into a flattened image at the\ndestination; when true, only the active qcow2 layer is migrated\nand the destination must already have access to the same backing\nchain as was used on the source.  (since 2.10)" },
    EnumVariantMeta { name: "XMultifdChannels", wire_name: "x-multifd-channels", payload_struct: None, payload_type: None, since: (2u32, 11u32, 0u32), until: Some((4u32, 0u32, 0u32)), deprecated: false, unstable: false, doc: "Number of channels used to migrate data in\nparallel. This is the same number that the\nnumber of sockets used for migration.  The\ndefault value is 2 (since 2.11)" },
    EnumVariantMeta { name: "XMultifdPageCount", wire_name: "x-multifd-page-count", payload_struct: None, payload_type: None, since: (2u32, 11u32, 0u32), until: Some((4u32, 0u32, 0u32)), deprecated: false, unstable: false, doc: "Number of pages sent together to a thread.\nThe default value is 16 (since 2.11)" },
    EnumVariantMeta { name: "XbzrleCacheSize", wire_name: "xbzrle-cache-size", payload_struct: None, payload_type: None, since: (2u32, 11u32, 0u32), until: None, deprecated: false, unstable: false, doc: "cache size to be used by XBZRLE migration.  It\nneeds to be a multiple of the target page size and a power of 2\n(Since 2.11)" },
    EnumVariantMeta { name: "MaxPostcopyBandwidth", wire_name: "max-postcopy-bandwidth", payload_struct: None, payload_type: None, since: (3u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Background transfer bandwidth during\npostcopy.  Defaults to 0 (unlimited).  In bytes per second.\n(Since 3.0)" },
    EnumVariantMeta { name: "CompressWaitThread", wire_name: "compress-wait-thread", payload_struct: None, payload_type: None, since: (3u32, 1u32, 0u32), until: Some((9u32, 1u32, 0u32)), deprecated: true, unstable: false, doc: "Controls behavior when all compression\nthreads are currently busy.  If true (default), wait for a free\ncompression thread to become available; otherwise, send the page\nuncompressed.  (Since 3.1)" },
    EnumVariantMeta { name: "MaxCpuThrottle", wire_name: "max-cpu-throttle", payload_struct: None, payload_type: None, since: (3u32, 1u32, 0u32), until: None, deprecated: false, unstable: false, doc: "maximum cpu throttle percentage.  Defaults to 99.\n(Since 3.1)" },
    EnumVariantMeta { name: "AnnounceInitial", wire_name: "announce-initial", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Initial delay (in milliseconds) before sending\nthe first announce (Since 4.0)" },
    EnumVariantMeta { name: "AnnounceMax", wire_name: "announce-max", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Maximum delay (in milliseconds) between packets in\nthe announcement (Since 4.0)" },
    EnumVariantMeta { name: "AnnounceRounds", wire_name: "announce-rounds", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Number of self-announce packets sent after\nmigration (Since 4.0)" },
    EnumVariantMeta { name: "AnnounceStep", wire_name: "announce-step", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Increase in delay (in milliseconds) between\nsubsequent packets in the announcement (Since 4.0)" },
    EnumVariantMeta { name: "TlsAuthz", wire_name: "tls-authz", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "ID of the 'authz' object subclass that provides access\ncontrol checking of the TLS x509 certificate distinguished name.\nThis object is only resolved at time of use, so can be deleted\nand recreated on the fly while the migration server is active.\nIf missing, it will default to denying access (Since 4.0)" },
    EnumVariantMeta { name: "MultifdChannels", wire_name: "multifd-channels", payload_struct: None, payload_type: None, since: (4u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Number of channels used to migrate data in\nparallel.  This is the same number that the number of sockets\nused for migration.  The default value is 2 (since 4.0)" },
    EnumVariantMeta { name: "ThrottleTriggerThreshold", wire_name: "throttle-trigger-threshold", payload_struct: None, payload_type: None, since: (5u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "The ratio of bytes_dirty_period and\nbytes_xfer_period to trigger throttling.  It is expressed as\npercentage.  The default value is 50.  (Since 5.0)" },
    EnumVariantMeta { name: "MultifdCompression", wire_name: "multifd-compression", payload_struct: None, payload_type: None, since: (5u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Which compression method to use.  Defaults to\nnone.  (Since 5.0)" },
    EnumVariantMeta { name: "MultifdZlibLevel", wire_name: "multifd-zlib-level", payload_struct: None, payload_type: None, since: (5u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Set the compression level to be used in live\nmigration, the compression level is an integer between 0 and 9,\nwhere 0 means no compression, 1 means the best compression\nspeed, and 9 means best compression ratio which will consume\nmore CPU.  Defaults to 1.  (Since 5.0)" },
    EnumVariantMeta { name: "MultifdZstdLevel", wire_name: "multifd-zstd-level", payload_struct: None, payload_type: None, since: (5u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Set the compression level to be used in live\nmigration, the compression level is an integer between 0 and 20,\nwhere 0 means no compression, 1 means the best compression\nspeed, and 20 means best compression ratio which will consume\nmore CPU.  Defaults to 1.  (Since 5.0)" },
    EnumVariantMeta { name: "CpuThrottleTailslow", wire_name: "cpu-throttle-tailslow", payload_struct: None, payload_type: None, since: (5u32, 1u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Make CPU throttling slower at tail stage.\nAt the tail stage of throttling, the Guest is very sensitive to\nCPU percentage while the @cpu-throttle -increment is excessive\nusually at tail stage.  If this parameter is true, we will\ncompute the ideal CPU percentage used by the Guest, which may\nexactly make the dirty rate match the dirty rate threshold.\nThen we will choose a smaller throttle increment between the one\nspecified by @cpu-throttle-increment and the one generated by\nideal CPU percentage.  Therefore, it is compatible to\ntraditional throttling, meanwhile the throttle increment won't\nbe excessive at tail stage.  The default value is false.\n(Since 5.1)" },
    EnumVariantMeta { name: "BlockBitmapMapping", wire_name: "block-bitmap-mapping", payload_struct: None, payload_type: None, since: (5u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Maps block nodes and bitmaps on them to\naliases for the purpose of dirty bitmap migration.  Such aliases\nmay for example be the corresponding names on the opposite site.\nThe mapping must be one-to-one, but not necessarily complete: On\nthe source, unmapped bitmaps and all bitmaps on unmapped nodes\nwill be ignored.  On the destination, encountering an unmapped\nalias in the incoming migration stream will result in a report,\nand all further bitmap migration data will then be discarded.\nNote that the destination does not know about bitmaps it does\nnot receive, so there is no limitation or requirement regarding\nthe number of bitmaps received, or how they are named, or on\nwhich nodes they are placed.  By default (when this parameter\nhas never been set), bitmap names are mapped to themselves.\nNodes are mapped to their block device name if there is one, and\nto their node name otherwise.  (Since 5.2)" },
    EnumVariantMeta { name: "XVcpuDirtyLimitPeriod", wire_name: "x-vcpu-dirty-limit-period", payload_struct: None, payload_type: None, since: (8u32, 1u32, 0u32), until: None, deprecated: false, unstable: true, doc: "Periodic time (in milliseconds) of dirty\nlimit during live migration.  Should be in the range 1 to\n1000ms.  Defaults to 1000ms.  (Since 8.1)" },
    EnumVariantMeta { name: "VcpuDirtyLimit", wire_name: "vcpu-dirty-limit", payload_struct: None, payload_type: None, since: (8u32, 1u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Dirtyrate limit (MB/s) during live migration.\nDefaults to 1.  (Since 8.1)" },
    EnumVariantMeta { name: "AvailSwitchoverBandwidth", wire_name: "avail-switchover-bandwidth", payload_struct: None, payload_type: None, since: (8u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "to set the available bandwidth that\nmigration can use during switchover phase.  **Note:** this does\nnot limit the bandwidth during switchover, but only for\ncalculations when making decisions to switchover.  By default,\nthis value is zero, which means QEMU will estimate the bandwidth\nautomatically.  This can be set when the estimated value is not\naccurate, while the user is able to guarantee such bandwidth is\navailable when switching over.  When specified correctly, this\ncan make the switchover decision much more accurate.\n(Since 8.2)" },
    EnumVariantMeta { name: "Mode", wire_name: "mode", payload_struct: None, payload_type: None, since: (8u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Migration mode.  See description in `MigMode`.  Default is\n'normal'.  (Since 8.2)" },
    EnumVariantMeta { name: "ZeroPageDetection", wire_name: "zero-page-detection", payload_struct: None, payload_type: None, since: (9u32, 0u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Whether and how to detect zero pages.  See\ndescription in `ZeroPageDetection`.  Default is 'multifd'.\n(since 9.0)" },
    EnumVariantMeta { name: "DirectIo", wire_name: "direct-io", payload_struct: None, payload_type: None, since: (9u32, 1u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Open migration files with O_DIRECT when possible.  This\nonly has effect if the @mapped-ram capability is enabled.\n(Since 9.1)" },
    EnumVariantMeta { name: "MultifdQatzipLevel", wire_name: "multifd-qatzip-level", payload_struct: None, payload_type: None, since: (9u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Set the compression level to be used in live\nmigration.  The level is an integer between 1 and 9, where 1\nmeans the best compression speed, and 9 means the best\ncompression ratio which will consume more CPU.  Defaults to 1.\n(Since 9.2)" },
    EnumVariantMeta { name: "CprExecCommand", wire_name: "cpr-exec-command", payload_struct: None, payload_type: None, since: (10u32, 2u32, 0u32), until: None, deprecated: false, unstable: false, doc: "Command to start the new QEMU process when @mode\nis @cpr-exec.  The first list element is the program's filename,\nthe remainder its arguments.  (Since 10.2)" },
    EnumVariantMeta { name: "XRdmaChunkSize", wire_name: "x-rdma-chunk-size", payload_struct: None, payload_type: None, since: (11u32, 1u32, 0u32), until: None, deprecated: false, unstable: true, doc: "" },
];
