static STRUCT_NetdevDgramOptions: StructMeta = StructMeta {
    name: "NetdevDgramOptions",
    doc: "Configuration info for datagram socket netdev.\n\nOnly `SocketAddress` types 'unix', 'inet' and 'fd' are supported.\n\nIf remote address is present and it's a multicast address, local\naddress is optional.  Otherwise local address is required and remote\naddress is optional.\n\n.. table:: Valid parameters combination table\n   :widths: auto\n\n   =============  ========  =====\n   remote         local     okay?\n   =============  ========  =====\n   absent         absent    no\n   absent         not fd    no\n   absent         fd        yes\n   multicast      absent    yes\n   multicast      present   yes\n   not multicast  absent    no\n   not multicast  present   yes\n   =============  ========  =====",
    fields: &FIELDS_NetdevDgramOptions,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (7u32, 2u32, 0u32),
    until: None,
};
