static STRUCT_QueryCpus: StructMeta = StructMeta {
    name: "query-cpus",
    doc: "Returns a list of information about each virtual CPU.\n\nThis command causes vCPU threads to exit to userspace, which causes\na small interruption to guest CPU execution. This will have a negative\nimpact on realtime guests and other latency sensitive guest workloads.\n\nFeatures:\n@deprecated: This command is deprecated, because it interferes with\n             the guest.  Use 'query-cpus-fast' instead to avoid the vCPU\n             interruption.\n\nReturns: a list of @CpuInfo for each virtual CPU\n\n\nExample:\n\n-> { \"execute\": \"query-cpus\" }\n<- { \"return\": [\n         {\n            \"CPU\":0,\n            \"current\":true,\n            \"halted\":false,\n            \"qom_path\":\"/machine/unattached/device[0]\",\n            \"arch\":\"x86\",\n            \"pc\":3227107138,\n            \"thread_id\":3134\n         },\n         {\n            \"CPU\":1,\n            \"current\":false,\n            \"halted\":true,\n            \"qom_path\":\"/machine/unattached/device[2]\",\n            \"arch\":\"x86\",\n            \"pc\":7108165,\n            \"thread_id\":3135\n         }\n      ]\n   }",
    fields: &FIELDS_QueryCpus,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (1u32, 0u32, 0u32),
    until: Some((6u32, 0u32, 0u32)),
};
