static STRUCT_QueryMigrate: StructMeta = StructMeta {
    name: "query-migrate",
    doc: "Return information about current migration process.  If migration is\nactive there will be another json-object with RAM migration status.\n\n\n.. qmp-example::\n   :title: Before the first migration\n\n    -> { \"execute\": \"query-migrate\" }\n    <- { \"return\": {} }\n\n.. qmp-example::\n   :title: Migration is done and has succeeded\n\n    -> { \"execute\": \"query-migrate\" }\n    <- { \"return\": {\n            \"status\": \"completed\",\n            \"total-time\":12345,\n            \"setup-time\":12345,\n            \"downtime\":12345,\n            \"ram\":{\n              \"transferred\":123,\n              \"remaining\":123,\n              \"total\":246,\n              \"duplicate\":123,\n              \"normal\":123,\n              \"normal-bytes\":123456,\n              \"dirty-sync-count\":15\n            }\n         }\n       }\n\n.. qmp-example::\n   :title: Migration is done and has failed\n\n    -> { \"execute\": \"query-migrate\" }\n    <- { \"return\": { \"status\": \"failed\" } }\n\n.. qmp-example::\n   :title: Migration is being performed\n\n    -> { \"execute\": \"query-migrate\" }\n    <- {\n          \"return\":{\n             \"status\":\"active\",\n             \"total-time\":12345,\n             \"setup-time\":12345,\n             \"expected-downtime\":12345,\n             \"ram\":{\n                \"transferred\":123,\n                \"remaining\":123,\n                \"total\":246,\n                \"duplicate\":123,\n                \"normal\":123,\n                \"normal-bytes\":123456,\n                \"dirty-sync-count\":15\n             }\n          }\n       }\n\n.. qmp-example::\n   :title: Migration is being performed and XBZRLE is active\n\n    -> { \"execute\": \"query-migrate\" }\n    <- {\n          \"return\":{\n             \"status\":\"active\",\n             \"total-time\":12345,\n             \"setup-time\":12345,\n             \"expected-downtime\":12345,\n             \"ram\":{\n                \"total\":1057024,\n                \"remaining\":1053304,\n                \"transferred\":3720,\n                \"duplicate\":10,\n                \"normal\":3333,\n                \"normal-bytes\":3412992,\n                \"dirty-sync-count\":15\n             },\n             \"xbzrle-cache\":{\n                \"cache-size\":67108864,\n                \"bytes\":20971520,\n                \"pages\":2444343,\n                \"cache-miss\":2244,\n                \"cache-miss-rate\":0.123,\n                \"encoding-rate\":80.1,\n                \"overflow\":34434\n             }\n          }\n       }",
    fields: &FIELDS_QueryMigrate,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (1u32, 0u32, 0u32),
    until: None,
};
