static STRUCT_QueryPci: StructMeta = StructMeta {
    name: "query-pci",
    doc: "Return information about the PCI bus topology of the guest.\n\nReturns: a list of info for each PCI bus.  Each bus is\n    represented by a json-object, which has a key with a json-array\n    of all PCI devices attached to it.  Each device is represented\n    by a json-object.\n\n\n.. qmp-example::\n\n    -> { \"execute\": \"query-pci\" }\n    <- { \"return\": [\n             {\n                \"bus\": 0,\n                \"devices\": [\n                   {\n                      \"bus\": 0,\n                      \"qdev_id\": \"\",\n                      \"slot\": 0,\n                      \"class_info\": {\n                         \"class\": 1536,\n                         \"desc\": \"Host bridge\"\n                      },\n                      \"id\": {\n                         \"device\": 32902,\n                         \"vendor\": 4663\n                      },\n                      \"function\": 0,\n                      \"regions\": [\n                      ]\n                   },\n                   {\n                      \"bus\": 0,\n                      \"qdev_id\": \"\",\n                      \"slot\": 1,\n                      \"class_info\": {\n                         \"class\": 1537,\n                         \"desc\": \"ISA bridge\"\n                      },\n                      \"id\": {\n                         \"device\": 32902,\n                         \"vendor\": 28672\n                      },\n                      \"function\": 0,\n                      \"regions\": [\n                      ]\n                   },\n                   {\n                      \"bus\": 0,\n                      \"qdev_id\": \"\",\n                      \"slot\": 1,\n                      \"class_info\": {\n                         \"class\": 257,\n                         \"desc\": \"IDE controller\"\n                      },\n                      \"id\": {\n                         \"device\": 32902,\n                         \"vendor\": 28688\n                      },\n                      \"function\": 1,\n                      \"regions\": [\n                         {\n                            \"bar\": 4,\n                            \"size\": 16,\n                            \"address\": 49152,\n                            \"type\": \"io\"\n                         }\n                      ]\n                   },\n                   {\n                      \"bus\": 0,\n                      \"qdev_id\": \"\",\n                      \"slot\": 2,\n                      \"class_info\": {\n                         \"class\": 768,\n                         \"desc\": \"VGA controller\"\n                      },\n                      \"id\": {\n                         \"device\": 4115,\n                         \"vendor\": 184\n                      },\n                      \"function\": 0,\n                      \"regions\": [\n                         {\n                            \"prefetch\": true,\n                            \"mem_type_64\": false,\n                            \"bar\": 0,\n                            \"size\": 33554432,\n                            \"address\": 4026531840,\n                            \"type\": \"memory\"\n                         },\n                         {\n                            \"prefetch\": false,\n                            \"mem_type_64\": false,\n                            \"bar\": 1,\n                            \"size\": 4096,\n                            \"address\": 4060086272,\n                            \"type\": \"memory\"\n                         },\n                         {\n                            \"prefetch\": false,\n                            \"mem_type_64\": false,\n                            \"bar\": 6,\n                            \"size\": 65536,\n                            \"address\": -1,\n                            \"type\": \"memory\"\n                         }\n                      ]\n                   },\n                   {\n                      \"bus\": 0,\n                      \"qdev_id\": \"\",\n                      \"irq\": 11,\n                      \"slot\": 4,\n                      \"class_info\": {\n                         \"class\": 1280,\n                         \"desc\": \"RAM controller\"\n                      },\n                      \"id\": {\n                         \"device\": 6900,\n                         \"vendor\": 4098\n                      },\n                      \"function\": 0,\n                      \"regions\": [\n                         {\n                            \"bar\": 0,\n                            \"size\": 32,\n                            \"address\": 49280,\n                            \"type\": \"io\"\n                         }\n                      ]\n                   }\n                ]\n             }\n          ]\n       }\n\nThis example has been shortened as the real response is too long.",
    fields: &FIELDS_QueryPci,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (1u32, 0u32, 0u32),
    until: None,
};
