static STRUCT_RemoveFd: StructMeta = StructMeta {
    name: "remove-fd",
    doc: "Remove a file descriptor from an fd set.\n\nErrors:\n    - If @fdset-id or @fd is not found, GenericError\n\n\n.. note:: The list of fd sets is shared by all monitor connections.\n\n.. note:: If @fd is not specified, all file descriptors in @fdset-id\n   will be removed.\n\n.. qmp-example::\n\n    -> { \"execute\": \"remove-fd\", \"arguments\": { \"fdset-id\": 1, \"fd\": 3 } }\n    <- { \"return\": {} }",
    fields: &FIELDS_RemoveFd,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (1u32, 2u32, 0u32),
    until: None,
};
