static STRUCT_SmpConfiguration: StructMeta = StructMeta {
    name: "SMPConfiguration",
    doc: "Schema for CPU topology configuration.  A missing value lets QEMU\nfigure out a suitable value based on the ones that are provided.\n\nThe members other than @cpus and @maxcpus define a topology of\ncontainers.\n\nThe ordering from highest/coarsest to lowest/finest is: @drawers,\n@books, @sockets, @dies, @clusters, @cores, @threads.\n\nDifferent architectures support different subsets of topology\ncontainers.\n\nFor example, s390x does not have clusters and dies, and the socket\nis the parent container of cores.",
    fields: &FIELDS_SmpConfiguration,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (6u32, 1u32, 0u32),
    until: None,
};
