static STRUCT_SnapshotDelete: StructMeta = StructMeta {
    name: "snapshot-delete",
    doc: "Delete a VM snapshot\n\nApplications should not assume that the snapshot delete is complete\nwhen this command returns.  The job commands / events must be used\nto determine completion and to fetch details of any errors that\narise.\n\n.. qmp-example::\n\n    -> { \"execute\": \"snapshot-delete\",\n         \"arguments\": {\n            \"job-id\": \"snapdelete0\",\n            \"tag\": \"my-snap\",\n            \"devices\": [\"disk0\", \"disk1\"]\n         }\n       }\n    <- { \"return\": { } }\n    <- {\"event\": \"JOB_STATUS_CHANGE\",\n        \"timestamp\": {\"seconds\": 1442124172, \"microseconds\": 744001},\n        \"data\": {\"status\": \"created\", \"id\": \"snapdelete0\"}}\n    <- {\"event\": \"JOB_STATUS_CHANGE\",\n        \"timestamp\": {\"seconds\": 1442125172, \"microseconds\": 744001},\n        \"data\": {\"status\": \"running\", \"id\": \"snapdelete0\"}}\n    <- {\"event\": \"JOB_STATUS_CHANGE\",\n        \"timestamp\": {\"seconds\": 1442126172, \"microseconds\": 744001},\n        \"data\": {\"status\": \"waiting\", \"id\": \"snapdelete0\"}}\n    <- {\"event\": \"JOB_STATUS_CHANGE\",\n        \"timestamp\": {\"seconds\": 1442127172, \"microseconds\": 744001},\n        \"data\": {\"status\": \"pending\", \"id\": \"snapdelete0\"}}\n    <- {\"event\": \"JOB_STATUS_CHANGE\",\n        \"timestamp\": {\"seconds\": 1442128172, \"microseconds\": 744001},\n        \"data\": {\"status\": \"concluded\", \"id\": \"snapdelete0\"}}\n    -> {\"execute\": \"query-jobs\"}\n    <- {\"return\": [{\"current-progress\": 1,\n                    \"status\": \"concluded\",\n                    \"total-progress\": 1,\n                    \"type\": \"snapshot-delete\",\n                    \"id\": \"snapdelete0\"}]}",
    fields: &FIELDS_SnapshotDelete,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (6u32, 0u32, 0u32),
    until: None,
};
