static STRUCT_XQueryVirtioQueueElement: StructMeta = StructMeta {
    name: "x-query-virtio-queue-element",
    doc: "Return the information about a VirtQueue's VirtQueueElement\n\nFeatures:\n\n@unstable: This command is meant for debugging.\n\n\n.. qmp-example::\n   :title: Introspect on virtio-net's VirtQueue 0 at index 5\n\n    -> { \"execute\": \"x-query-virtio-queue-element\",\n         \"arguments\": { \"path\": \"/machine/peripheral-anon/device[1]/virtio-backend\",\n                        \"queue\": 0,\n                        \"index\": 5 }\n       }\n    <- { \"return\": {\n             \"index\": 5,\n             \"name\": \"virtio-net\",\n             \"descs\": [\n                 {\n                     \"flags\": [\"write\"],\n                     \"len\": 1536,\n                     \"addr\": 5257305600\n                 }\n             ],\n             \"avail\": {\n                 \"idx\": 256,\n                 \"flags\": 0,\n                 \"ring\": 5\n             },\n             \"used\": {\n                 \"idx\": 13,\n                 \"flags\": 0\n             }\n         }\n       }\n\n.. qmp-example::\n   :title: Introspect on virtio-crypto's VirtQueue 1 at head\n\n    -> { \"execute\": \"x-query-virtio-queue-element\",\n         \"arguments\": { \"path\": \"/machine/peripheral/crypto0/virtio-backend\",\n                        \"queue\": 1 }\n       }\n    <- { \"return\": {\n             \"index\": 0,\n             \"name\": \"virtio-crypto\",\n             \"descs\": [\n                 {\n                     \"flags\": [],\n                     \"len\": 0,\n                     \"addr\": 8080268923184214134\n                 }\n             ],\n             \"avail\": {\n                 \"idx\": 280,\n                 \"flags\": 0,\n                 \"ring\": 0\n             },\n             \"used\": {\n                 \"idx\": 280,\n                 \"flags\": 0\n             }\n         }\n       }\n\n.. qmp-example::\n   :title: Introspect on virtio-scsi's VirtQueue 2 at head\n\n    -> { \"execute\": \"x-query-virtio-queue-element\",\n         \"arguments\": { \"path\": \"/machine/peripheral-anon/device[2]/virtio-backend\",\n                        \"queue\": 2 }\n       }\n    <- { \"return\": {\n             \"index\": 19,\n             \"name\": \"virtio-scsi\",\n             \"descs\": [\n                 {\n                     \"flags\": [\"used\", \"indirect\", \"write\"],\n                     \"len\": 4099327944,\n                     \"addr\": 12055409292258155293\n                 }\n             ],\n             \"avail\": {\n                 \"idx\": 1147,\n                 \"flags\": 0,\n                 \"ring\": 19\n             },\n             \"used\": {\n                 \"idx\": 280,\n                 \"flags\": 0\n             }\n         }\n       }",
    fields: &FIELDS_XQueryVirtioQueueElement,
    is_union: false,
    discriminator_field: None,
    branch_enum: None,
    free_form: false,
    since: (7u32, 2u32, 0u32),
    until: None,
};
